"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

type NoteProps = Omit<React.ComponentProps<"button">, "children"> & {
  /** The word or phrase being annotated. For expand, the abbreviation itself, as a string. */
  children: React.ReactNode
  /** The note. Phrasing content only; a sentence or two. For ossia, a few words; for expand, the words the abbreviation stands for, as a string. */
  note: React.ReactNode
  /**
   * leader: a leader line draws out to the note. ossia: the note is always there,
   * set small in the line space above the term. expand: the abbreviation's letters
   * move apart and the words grow between them. revise: pressed, the term is struck
   * through and the note, its replacement, is written in after it.
   */
  variant?: "leader" | "ossia" | "expand" | "revise"
}

type Part = { text: string; keep: boolean }

/**
 * Splits `full` into the letters `term` keeps and the rest, which grows in between.
 * A kept letter is the start of a word or a capital inside one (HyperText); a word
 * that keeps none ("and") grows whole. Null if the term's letters aren't found in order.
 */
function initials(term: string, full: string): Part[][] | null {
  const letters = [...term].filter((c) => /[\p{L}\p{N}]/u.test(c))
  let k = 0
  const words = full.trim().split(/\s+/).map((word) => {
    const parts: Part[] = []
    ;[...word].forEach((c, i) => {
      const keep = k < letters.length && c.toLowerCase() === letters[k].toLowerCase() && (i === 0 || c !== c.toLowerCase())
      const text = keep ? letters[k++] : c
      const last = parts[parts.length - 1]
      if (last && last.keep === keep && !keep) last.text += text
      else parts.push({ text, keep })
    })
    return parts
  })
  return k === letters.length && letters.length > 0 ? words : null
}

/**
 * Marginalia: a dotted term. Point at it or focus it and a leader line draws
 * out to the note. Leaving plays it backwards; Escape puts it away.
 */
function Note({ children, note, variant = "leader", className, onKeyDown, onClick, ...props }: NoteProps) {
  const id = React.useId()
  const [open, setOpen] = React.useState(false)

  if (variant === "ossia") {
    return (
      <span data-slot="note" data-variant="ossia" className={cn("db-note", className)} {...(props as React.ComponentProps<"span">)}>
        {children}
        <span data-slot="note-text" className="db-note-text">
          <span className="db-sr"> (</span>
          {note}
          <span className="db-sr">)</span>
        </span>
      </span>
    )
  }

  if (variant === "revise") {
    // The editor's correction: the pen strikes the term, and the word that replaces it is written in after it.
    // A span, not a button, so a struck phrase can break across lines as the sentence does.
    const toggle = () => setOpen((o) => !o)
    return (
      <span
        role="button"
        tabIndex={0}
        aria-expanded={open}
        data-slot="note"
        data-variant="revise"
        className={cn("db-note", className)}
        {...(props as React.ComponentProps<"span">)}
        onClick={(e) => {
          onClick?.(e as unknown as React.MouseEvent<HTMLButtonElement>)
          toggle()
        }}
        onKeyDown={(e) => {
          onKeyDown?.(e as unknown as React.KeyboardEvent<HTMLButtonElement>)
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            toggle()
          }
          if (e.key === "Escape") setOpen(false)
        }}
      >
        <span className="db-sr">{open ? <><del>{children}</del> <ins>{note}</ins></> : children}</span>
        <span className="db-note-was" aria-hidden="true">{children}</span>
        {/* A real space, so that where the correction wraps to the next line the space falls away at the break. */}
        {open || String((props as Record<string, unknown>)["data-force"] ?? "").includes("open") ? " " : null}
        <span className="db-note-now" aria-hidden="true">{note}</span>
      </span>
    )
  }

  const words = variant === "expand" && typeof children === "string" && typeof note === "string" ? initials(children, note) : null
  if (words) {
    // A span, not a button: a button can't break across lines, and the words it grows into must.
    const toggle = () => setOpen((o) => !o)
    return (
      <span
        role="button"
        tabIndex={0}
        dir="auto"
        aria-expanded={open}
        aria-describedby={id}
        data-slot="note"
        data-variant="expand"
        className={cn("db-note", className)}
        {...(props as React.ComponentProps<"span">)}
        onClick={(e) => {
          onClick?.(e as unknown as React.MouseEvent<HTMLButtonElement>)
          toggle()
        }}
        onKeyDown={(e) => {
          onKeyDown?.(e as unknown as React.KeyboardEvent<HTMLButtonElement>)
          if (e.key === "Enter" || e.key === " ") {
            e.preventDefault()
            toggle()
          }
          if (e.key === "Escape") setOpen(false)
        }}
      >
        <span className="db-sr">{children}</span>
        <span aria-hidden="true">
          {words.map((parts, w) => (
            <React.Fragment key={w}>
              {w > 0 ? <span className="db-note-grow">{" "}</span> : null}
              <span className="db-note-word">
                {parts.map((p, i) => (p.keep ? <span key={i} className="db-note-keep">{p.text}</span> : <span key={i} className="db-note-grow">{p.text}</span>))}
              </span>
            </React.Fragment>
          ))}
        </span>
        <span id={id} hidden>{note}</span>
      </span>
    )
  }

  return (
    <button
      type="button"
      data-slot="note"
      aria-describedby={id}
      className={cn("db-note", className)}
      onClick={onClick}
      onKeyDown={(e) => {
        onKeyDown?.(e)
        if (e.key === "Escape") e.currentTarget.blur()
      }}
      {...props}
    >
      {children}
      <span data-slot="note-text" id={id} aria-hidden="true" className="db-note-text">
        {note}
      </span>
    </button>
  )
}

export { Note, type NoteProps }

@layer components {
  /* ── db-note ── marginalia: a leader line draws out to the note */
  .db-note:not([data-variant]) {
    position: relative; display: inline; appearance: none; border: 0; background: none; margin: 0; padding: 0;
    font: inherit; color: inherit; cursor: help;
    text-decoration-line: underline; text-decoration-style: dotted; text-decoration-thickness: var(--db-hairline);
    text-decoration-color: var(--db-pencil); text-underline-offset: 0.24em;
  }
  .db-note:not([data-variant]) {
    padding-inline: 0.12em; margin-inline: -0.12em; box-decoration-break: clone; -webkit-box-decoration-break: clone;
    background: linear-gradient(var(--db-mark), var(--db-mark)) no-repeat 100% 0 / 0% 100%;
    transition: background-size var(--db-moderato) var(--db-exhale) 180ms, background-position 0s, color 0s linear calc(180ms + var(--db-allegro));
  }
  /* In: mark, anchor, line, note. Out: the same, backwards. */
  .db-note:not([data-variant])::before {
    content: ""; position: absolute; inset-inline-start: calc(0.6em - 2px); inset-block-start: calc(100% + 0.15em - 2px); z-index: 1;
    inline-size: 5px; block-size: 5px; border-radius: 50%; background: var(--db-ink);
    scale: 0; transition: scale var(--db-moderato) var(--db-spiccato) 140ms;
  }
  .db-note:not([data-variant]):is(:hover, :focus-visible, [data-force~="hover"]) { background-position: 0 0; background-size: 100% 100%; color: var(--db-on-mark); text-decoration-color: transparent; transition-delay: 0s; }
  .db-note:not([data-variant]):is(:hover, :focus-visible, [data-force~="hover"])::before { scale: 1; transition-delay: 60ms; }
  .db-note:not([data-variant])::after {
    content: ""; position: absolute; inset-inline-start: 0.6em; inset-block-start: calc(100% + 0.15em);
    inline-size: var(--db-hairline); block-size: 2em; background: var(--db-ink);
    scale: 1 0; transform-origin: top; transition: scale var(--db-moderato) var(--db-exhale) 60ms;
  }
  .db-note:not([data-variant]) > .db-note-text {
    position: absolute; z-index: 5; inset-inline-start: 0; inset-block-start: calc(100% + 2.1em);
    inline-size: max-content; max-inline-size: min(28ch, calc(100vw - 2.5rem)); padding: 0.55em 0.95em 0.6em; border-radius: 1em;
    background: var(--db-ink); color: var(--db-paper);
    font-family: var(--db-voice); font-style: normal; font-weight: 450; font-size: var(--db-pp); line-height: var(--db-pp-lh); letter-spacing: var(--db-pp-tr);
    text-align: start; white-space: normal; text-wrap: balance;
    clip-path: circle(0 at 0.6em 0); pointer-events: none;
    /* Hidden, the note leaves layout: one near the page's edge must not make the page scroll sideways. */
    display: none;
    transition: clip-path var(--db-moderato) var(--db-breath), display var(--db-moderato) allow-discrete;
  }
  .db-note:not([data-variant]):is(:hover, :focus-visible, [data-force~="hover"])::after { scale: 1 1; transition-delay: 120ms; }
  .db-note:not([data-variant]):is(:hover, :focus-visible, [data-force~="hover"]) > .db-note-text {
    display: block; clip-path: circle(150% at 0.6em 0); pointer-events: auto;
    transition: clip-path var(--db-andante) var(--db-exhale) 300ms, display 0s allow-discrete;
    @starting-style { clip-path: circle(0 at 0.6em 0); }
  }

  /* ossia: the note is always there, small, in the line space above the term, as a score prints an ossia bar over the staff.
     The term's line opens to make room; the note starts where the term starts, as an ossia starts with its bar, and may run on past its end. Pointing inks it. */
  .db-note[data-variant="ossia"] { position: relative; color: var(--db-ink); display: inline-block; padding-block-start: calc(var(--db-pp) * 1.25); }
  .db-note[data-variant="ossia"] > .db-note-text {
    position: absolute; inset-block-start: 0; inset-inline-start: 0; white-space: nowrap;
    font-family: var(--db-voice); font-style: normal; font-weight: 450; font-size: var(--db-pp); line-height: 1; letter-spacing: var(--db-pp-tr);
    color: var(--db-pencil); transition: color var(--db-allegro);
  }
  .db-note[data-variant="ossia"]:is(:hover, [data-force~="hover"]) > .db-note-text { color: var(--db-ink); }

  /* expand: an abbreviation that opens into its words. Pressed, the letters move apart and each word grows out of its initial;
     a word with none ("and") grows whole. The initials stay in ink, the rest arrives in graphite. */
  .db-note[data-variant="expand"] {
    cursor: pointer; interpolate-size: allow-keywords; color: var(--db-ink);
    text-decoration-line: underline; text-decoration-style: dotted; text-decoration-thickness: var(--db-hairline);
    text-decoration-color: var(--db-pencil); text-underline-offset: 0.24em; transition: text-decoration-color var(--db-allegro);
  }
  .db-note[data-variant="expand"]:is(:hover, [data-force~="hover"]) { text-decoration-color: var(--db-ink); }
  .db-note[data-variant="expand"]:is([aria-expanded="true"], [data-force~="open"]) { text-decoration-color: transparent; }
  .db-note-word { white-space: nowrap; }
  .db-note-grow {
    display: inline-block; inline-size: 0; overflow-x: clip; vertical-align: top; white-space: pre; color: var(--db-graphite); opacity: 0;
    transition: inline-size var(--db-moderato) var(--db-exhale), opacity var(--db-moderato) var(--db-exhale);
  }
  .db-note[data-variant="expand"]:is([aria-expanded="true"], [data-force~="open"]) .db-note-grow { inline-size: auto; opacity: 1; }

  /* revise: the editor's correction, after the Basquiat sheet's struck headline and the Weingart letter's typed page. At rest
     the term is dotted like the others; pointing sketches the strike in pencil, as the checkbox does. Pressed, the pen
     strikes it in ink, running past the words as a hand does, the struck words step back to pencil, and the replacement
     is written in after them in the italic, its box opening from the start as a pen moves. Pressed again, both lift. */
  .db-note[data-variant="revise"] { cursor: pointer; interpolate-size: allow-keywords; color: var(--db-ink); }
  .db-note-was {
    --y: 60%;
    padding-inline: 0.1em; margin-inline: -0.1em; /* the pen runs a little past the words, short of the word before */
    text-decoration-line: underline; text-decoration-style: dotted; text-decoration-thickness: var(--db-hairline);
    text-decoration-color: var(--db-pencil); text-underline-offset: 0.24em;
    background:
      linear-gradient(var(--db-ink), var(--db-ink)) no-repeat 100% var(--y) / 0% var(--db-stroke),
      linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 100% var(--y) / 0% var(--db-hairline);
    -webkit-box-decoration-break: clone; box-decoration-break: clone;
    transition: background-size var(--db-moderato) var(--db-breath), background-position 0s, color var(--db-moderato) var(--db-breath), text-decoration-color var(--db-allegro);
  }
  .db-note[data-variant="revise"]:is(:hover, [data-force~="hover"]):not([aria-expanded="true"], [data-force~="open"]) > .db-note-was { text-decoration-color: var(--db-ink); background-position: 100% var(--y), 0 var(--y); background-size: 0% var(--db-stroke), 100% var(--db-hairline); }
  .db-note[data-variant="revise"]:is([aria-expanded="true"], [data-force~="open"]) > .db-note-was { color: var(--db-pencil); text-decoration-color: transparent; background-position: 0 var(--y), 100% var(--y); background-size: 100% var(--db-stroke), 0% var(--db-hairline); }
  :is([dir="rtl"], [dir="rtl"] *).db-note[data-variant="revise"] > .db-note-was { background-position: 0 var(--y), 0 var(--y); }
  :is([dir="rtl"], [dir="rtl"] *).db-note[data-variant="revise"]:is(:hover, [data-force~="hover"]):not([aria-expanded="true"], [data-force~="open"]) > .db-note-was { background-position: 0 var(--y), 100% var(--y); }
  :is([dir="rtl"], [dir="rtl"] *).db-note[data-variant="revise"]:is([aria-expanded="true"], [data-force~="open"]) > .db-note-was { background-position: 100% var(--y), 0 var(--y); }
  .db-note-now {
    display: inline-block; inline-size: 0; overflow-x: clip; overflow-clip-margin: 0.2em; white-space: pre; opacity: 0;
    font-family: var(--db-expression); font-style: italic; font-size: calc(var(--db-expression-scale) * 1em); line-height: 1;
    transition: inline-size var(--db-moderato) var(--db-exhale), opacity var(--db-allegro);
  }
  /* The strike draws first; the word is written in once the pen has crossed. */
  .db-note[data-variant="revise"]:is([aria-expanded="true"], [data-force~="open"]) > .db-note-now { inline-size: auto; opacity: 1; transition-delay: var(--db-allegro); }
  @media (forced-colors: active) {
    /* Forced colours drop the gradients that draw the strike; the plain line-through says it instead. */
    .db-note[data-variant="revise"]:is([aria-expanded="true"], [data-force~="open"]) > .db-note-was { text-decoration: line-through CanvasText; }
  }
}
